import hashlib,json,math,sys
from fractions import Fraction as Q
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.patches import FancyBboxPatch,FancyArrowPatch
import numpy as np
ROOT=Path(__file__).resolve().parents[1]
DATA=ROOT/'reviews/exact_example_results.json';D=json.loads(DATA.read_text());OUT=ROOT/'figures';OUT.mkdir(exist_ok=True)
C=D['cases']['coordinate'];R=D['cases']['rotated'];CS=C['states'];RS=R['states']
BLUE='#245989';TEAL='#117f78';ORANGE='#bd6935';RED='#a33f50';GRAY='#687884';LIGHT='#edf3f6';INK='#152b3c'
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':11,'axes.labelcolor':INK,'text.color':INK,'axes.titlecolor':INK,'axes.spines.top':False,'axes.spines.right':False,'axes.edgecolor':'#bcc9d0','axes.grid':False,'savefig.facecolor':'white','pdf.fonttype':42,'ps.fonttype':42,'figure.dpi':140})
CAT=[];LAYOUT=[]
def f(x):return float(Q(x))
def mat(x):return np.array([[f(v) for v in row] for row in x])
def make(title,subtitle,cols=1):
    fig,axs=plt.subplots(1,cols,figsize=(10.4,5.9),squeeze=False)
    fig.subplots_adjust(left=.095,right=.965,bottom=.18,top=.76,wspace=.34)
    fig.text(.065,.93,title,size=19,weight='bold',color=INK)
    fig.text(.065,.85,subtitle,size=11,color=GRAY)
    return fig,axs[0]
def foot(fig,s):fig.text(.065,.07,s,size=9,color=GRAY)
def save(fig,stem,caption,scope,inputs):
    foot(fig,scope)
    fig.canvas.draw();renderer=fig.canvas.get_renderer();outside=[]
    skipped=set()
    for ax in fig.axes:
        for axis in [ax.xaxis,ax.yaxis]:
            lo,hi=sorted(axis.get_view_interval())
            for tick in axis.get_major_ticks()+axis.get_minor_ticks():
                if not lo<=tick.get_loc()<=hi:
                    skipped.update([id(tick.label1),id(tick.label2)])
    for artist in fig.findobj(matplotlib.text.Text):
        if id(artist) in skipped or not artist.get_visible() or not artist.get_text():continue
        b=artist.get_window_extent(renderer)
        if b.width and b.height and (b.x0<0 or b.y0<0 or b.x1>fig.bbox.width or b.y1>fig.bbox.height):outside.append(artist.get_text())
    if outside:raise RuntimeError(f'{stem}: text outside canvas {outside}')
    for ext in ['pdf','png']:
        temporary=OUT/f'.{stem}.tmp.{ext}'
        fig.savefig(temporary,dpi=180)
        temporary.replace(OUT/f'{stem}.{ext}')
    paths={ext:str((OUT/f'{stem}.{ext}').relative_to(ROOT)) for ext in ['pdf','png']}
    CAT.append(dict(stem=stem,caption=caption,scope=scope,inputs=inputs,paths=paths,sha256={ext:hashlib.sha256((OUT/f'{stem}.{ext}').read_bytes()).hexdigest() for ext in paths}))
    LAYOUT.append(dict(stem=stem,text_outside_canvas=outside,png_width=1872,png_height=1062))
    plt.close(fig)
def box(ax,x,y,w,h,text,color=BLUE):
    ax.add_patch(FancyBboxPatch((x,y),w,h,boxstyle='round,pad=0.015,rounding_size=0.035',facecolor=LIGHT,edgecolor=color,lw=1.5));ax.text(x+w/2,y+h/2,text,ha='center',va='center',size=11,color=INK)
def arrow(ax,a,b,color=GRAY):ax.add_patch(FancyArrowPatch(a,b,arrowstyle='-|>',mutation_scale=14,color=color,lw=1.4))
def off(ax):ax.set_xlim(0,1);ax.set_ylim(0,1);ax.axis('off')
def fmt(x):return str(Q(x))
def matrix_panel(ax,A,title,decimal=False):
    ar=mat(A);ax.imshow(ar,cmap='Blues',aspect='equal',vmin=min(0,ar.min()),vmax=max(1,ar.max()));ax.set_xticks([]);ax.set_yticks([]);ax.set_title(title,pad=12,size=12)
    for i,row in enumerate(A):
        for j,v in enumerate(row):ax.text(j,i,f'{f(v):.6g}' if decimal else fmt(v),ha='center',va='center',color=('white' if ar[i,j]>max(1,ar.max())*.5 else INK),size=11)
def ellipse(ax,mean,cov,color,label,scale=1):
    vals,vecs=np.linalg.eigh(mat(cov));theta=np.linspace(0,2*np.pi,801);xy=np.array(mean,dtype=float)[:,None]+scale*vecs@np.diag(np.sqrt(np.maximum(vals,0)))@np.array([np.cos(theta),np.sin(theta)])
    ax.plot(xy[0],xy[1],color=color,lw=2,label=label);ax.scatter(*np.array(mean,dtype=float),color=color,s=24)

fig,(ax,)=make('The inference contract','One observation. One returned gain. Two numerical guarantees.');off(ax)
for x,y,txt in [(.02,.61,'Exact model\nP = LLᵀ, R ≥ σI'),(.37,.61,'Complete packets\nQₐ and Πᵦ'),(.72,.61,'Exact cached search\nGain B'),(.72,.1,'Rounded verifier\nScore ≤ ε²'),(.37,.1,'Gaussian law\nW₂ ≤ ε'),(.02,.1,'Parameter intervals\nEvery radius ≤ δ')]:box(ax,x,y,.25,.25,txt)
for a,b in [((.27,.735),(.37,.735)),((.62,.735),(.72,.735)),((.845,.61),(.845,.35)),((.72,.225),(.62,.225)),((.37,.225),(.27,.225))]:arrow(ax,a,b)
