fig,(ax,)=make('A Gaussian observation update','Coordinate example: H = [1  1], y = 1, P = diag(4, 1), R = 1.');ellipse(ax,[0,0],C['P'],BLUE,'Prior: one standard-deviation contour');ellipse(ax,[f(v) for v in C['posterior_mean']],C['posterior_covariance'],TEAL,'Chosen posterior version: same contour level');xs=np.linspace(-2.5,2.5,100);ax.plot(xs,1-xs,color=ORANGE,ls='--',lw=1.5,label='Observation relation x₁ + x₂ = 1');ax.set(xlabel='x₁',ylabel='x₂',xlim=(-2.5,2.5),ylim=(-2,2));ax.set_aspect('equal');ax.legend(fontsize=8.5,loc='lower left');save(fig,'02_gaussian_update_geometry','The coordinate prior has covariance diag(4,1). The chosen Gaussian posterior version has mean (2/3,1/6) and covariance [[4/3,-2/3],[-2/3,5/6]]. Contours are one standard-deviation level sets, not confidence regions. Observation noise has variance one, so the dashed observation relation is not a support constraint.','Numerical contour rendering from exact rational matrices; no interval-certified curve.',['examples/adaptive_coordinate.json','coordinate.posterior_covariance'])

fig,(ax,)=make('A singular prior remains a valid Gaussian','Rotated example: P = [[1, 1], [1, 1]] has rank one.');ax.plot([-2,2],[-2,2],color=BLUE,lw=7,alpha=.4,label='Prior support segment ±2 latent standard deviations');t=2/math.sqrt(3);ax.plot([-t,t],[-t,t],color=TEAL,lw=3,label='Posterior segment at the same latent level');ax.scatter([1],[-1],color=ORANGE,s=65,label='Observed y = (1, −1)');ax.plot([-2,2],[2,-2],color=GRAY,ls=':',lw=1);ax.set(xlabel='x₁',ylabel='x₂',xlim=(-2.3,2.3),ylim=(-2.3,2.3));ax.set_aspect('equal');ax.legend(fontsize=8.2,loc='upper left');save(fig,'03_singular_prior','The rank-one prior and chosen Gaussian posterior are supported on x₁=x₂; the posterior covariance is P/3. The supplied observation y=(1,-1) lies in the complementary direction and produces posterior mean zero. The plotted finite segments mark two latent standard deviations, rather than the full unbounded support.','Singular law is supported on a line; finite segments illustrate scale only.',['examples/adaptive_rotated.json','rotated.P','rotated.posterior_covariance'])

fig,axs=make('Packets account for the whole residual','At B₀ = 0, F = PHᵀ = (4, 1)ᵀ. Orthogonal packets split the energy.',3)
for ax,A,title in zip(axs,[[['4'],['1']],[['4'],['0']],[['0'],['1']]],['Full residual F','Q₀F: energy 16','Q₁F: energy 1']):matrix_panel(ax,A,title)
fig.text(.5,.12,'‖F‖² = 16 + 1 = 17',ha='center',size=14,color=TEAL);save(fig,'04_packet_decomposition','The coordinate output projectors select the first and second coordinates. Their residual components are orthogonal and their squared Frobenius energies add exactly to the full residual energy. Input packet splitting is trivial in this one-dimensional observation space.','Exact matrices and exact energy identity at the coordinate initial gain.',['coordinate.states[0]'])

fig,(ax,)=make('Selective updates reduce packet energy','Coordinate example: each chosen packet energy is multiplied by 1/49.');n=[s['iteration'] for s in CS]
for a,color in [(0,BLUE),(1,TEAL)]:ax.step(n,[f(s['energies'][a]) for s in CS],where='post',marker='o',color=color,label=f'Packet {a}')
ax.plot(n,[f(s['total']) for s in CS],color=GRAY,ls='--',marker='.',label='Total energy');ax.set(yscale='log',xlabel='Completed selective updates',ylabel='Squared Frobenius energy',xticks=n);ax.legend(fontsize=10);save(fig,'05_residual_energy','The cached coordinate trajectory alternates labels 0,1,0,1,0,1. Only the selected packet changes at each step. After six updates the packet energies are 16/117649 and 1/117649, and total residual energy is 17/117649.','Exact trajectory values; logarithmic display uses numerical coordinates.',['coordinate.states'])

fig,(ax,)=make('The gain moves one packet at a time','Coordinate trajectory from B₀ = (0, 0)ᵀ to B₆ = (228/343, 57/343)ᵀ.');xy=np.array([[f(s['gain'][i][0]) for i in range(2)] for s in CS]);ax.plot(xy[:,0],xy[:,1],color=BLUE,lw=1.5);ax.scatter(xy[:,0],xy[:,1],c=range(len(CS)),cmap='viridis',s=45,zorder=3)
for i,(x,y) in enumerate(xy):
    if i<=4:ax.annotate(str(i),(x,y),xytext=(6,8),textcoords='offset points',size=10)
