rows=[['Entry','Before','After selecting 0'],['Gain B','(0, 0)ᵀ','(4/7, 0)ᵀ'],['Residual G₀','(4, 0)ᵀ','(4/7, 0)ᵀ'],['Energy e₀','16','16/49'],['Residual G₁','(0, 1)ᵀ','(0, 1)ᵀ'],['Energy e₁','1','1'],['Total','17','65/49']]
tab=ax.table(cellText=rows[1:],colLabels=rows[0],cellLoc='center',loc='center',colWidths=[.27,.30,.40]);tab.auto_set_font_size(False);tab.set_fontsize(11);tab.scale(1,1.9)
