fig,(ax,)=make('A guaranteed rate can be conservative','Coordinate score a(Bₙ) and theorem bound (85/98)ⁿ a(B₀).');ax.semilogy(n,[f(s['score']) for s in CS],color=TEAL,marker='o',label='Exact score a(Bₙ)');ax.semilogy(n,[f(s['geometric_bound']) for s in CS],color=BLUE,marker='s',label='Uniform geometric upper bound');ax.axhline((1/20)**2/4,color=ORANGE,ls='--',label='Exact search target ε²/4');ax.set(xlabel='Completed selective updates',ylabel='Score / squared distance bound',xticks=n);ax.legend(fontsize=9);save(fig,'08_geometric_bound','The uniform greedy rate is r=85/98 for this two-packet coordinate model. The exact score starts at 34 and ends at 34/117649. The theorem bound rⁿ·34 is valid but much looser here. The large sufficient fuel 410093 is a guaranteed horizon, rather than the observed six-update count or a tight estimate.','Uniform contraction theorem illustrated on a finite exact trajectory.',['coordinate.rate','coordinate.states','coordinate.result.fuel'])

fig,(ax,)=make('Search leaves room for final verification','Coordinate example: the verifier and the search use different thresholds.');labels=['Exact final score','Rounded score at p = 12','Exact search target ε²/4','Requested tolerance ε²'];values=[f(CS[-1]['score']),f(C['result']['rounded_score']),(1/20)**2/4,(1/20)**2];colors=[TEAL,BLUE,ORANGE,GRAY];fig.subplots_adjust(left=.31,right=.93);y=np.arange(4);ax.barh(y,values,color=colors,height=.55);ax.set_yticks(y,labels);ax.invert_yaxis();ax.set(xlabel='Squared distance certificate score',xlim=(0,.0028),xticks=[0,.0005,.001,.0015,.002,.0025]);ax.ticklabel_format(axis='x',style='sci',scilimits=(-3,-3));
for i,value in enumerate(values):ax.text(value+.000035,i,f'{value:.7f}',va='center',size=10)
save(fig,'09_stopping_slack','Cached search stops when exact score is at most ε²/4. At the returned coordinate gain, exact score is 34/117649 and the rounded score at precision 12 is 481/1048576. Both are below ε²=1/400. A sufficient fallback allows another ε²/4 inflation, leaving the rounded score at most ε²/2.','Exact stopping margin and actual successful rounded-verifier score.',['coordinate.result','coordinate.epsilon'])

fig,(ax,)=make('Outward rounding encloses the exact value','Hand example: x = 1/3 with p = 4 fractional binary bits.');ax.axhline(0,color=GRAY,lw=1);lo,hi=.25,.375;ax.plot([lo,hi],[0,0],color=TEAL,lw=12,alpha=.35);ax.scatter([5/16],[0],color=BLUE,s=85,zorder=3);ax.scatter([1/3],[0],color=ORANGE,s=85,zorder=3,marker='D');ax.vlines([lo,hi],-.12,.12,color=TEAL,lw=2);ax.text(5/16,-.22,'center c = 5/16',ha='center',color=BLUE);ax.text(1/3,.25,'exact x = 1/3',ha='center',color=ORANGE);ax.text(lo,-.22,'1/4',ha='center');ax.text(hi,-.22,'3/8',ha='center');ax.text(.315,.58,'radius r = 1/16\n|x − c| ≤ r',ha='center',size=14);ax.set(xlim=(.21,.415),ylim=(-.45,.8),yticks=[],xticks=[.25,.3125,.375]);ax.set_xlabel('Exact rational value');save(fig,'10_dyadic_interval','Down-rounding 1/3 to four fractional bits gives center 5/16. Up-rounding the lost magnitude gives radius 1/16, so the ball is [1/4,3/8] and contains 1/3. This is center/radius fixed-point arithmetic with unbounded mathematical integer parts, rather than an IEEE-754 format.','Hand-computable exact dyadic enclosure; no floating-point error claim.',['dyadic','checks/rounded_certificate.py'])

fig,(ax,)=make('More verifier precision tightens this fixture','Final coordinate gain is fixed throughout this plot.');fig.subplots_adjust(bottom=.27);ps=[s['precision'] for s in C['precision_scores']];vs=[f(s['score']) for s in C['precision_scores']];ax.semilogy(ps,vs,color=BLUE,marker='o',label='Rounded score at p bits');ax.axhline((1/20)**2,color=ORANGE,ls='--',label='ε² = 1/400');ax.axhline(f(CS[-1]['score']),color=TEAL,ls=':',label='Exact score');ax.scatter([4,12],[vs[3],vs[11]],s=100,facecolors='none',edgecolors=RED,label='Requested probes: 4 fails, 12 passes');ax.set(xlabel='Fractional binary precision p',ylabel='Certificate score',xticks=[1,4,8,12,16]);ax.legend(fontsize=8.7,loc='upper right');fig.text(.5,.12,'Sufficient fallback precision = 72 bits; it was not needed.',ha='center',size=11);save(fig,'11_precision_verification','The final coordinate gain is evaluated at precisions 1 through 16. Probe 4 gives score 25/16 and fails; probe 12 gives 481/1048576 and passes. The theorem-backed conservative fallback precision is 72. The observed shape is fixture-specific and is not a new claim that every precision curve is strictly decreasing.','Exact rational verifier scores; fixed gain, fixed rounded computation graph.',['coordinate.precision_scores','coordinate.sufficient_precision'])

fig,axs=make('Joseph covariance retains a nonnegative excess','Σ(B) = Σ(K) + (B − K) S (B − K)ᵀ. Coordinate final gain.',3);A=C['posterior_covariance'];J=CS[-1]['covariance'];E=[[str(Q(J[i][j])-Q(A[i][j])) for j in range(2)] for i in range(2)]
