fig,(ax,)=make('Returned intervals enclose the Joseph parameters','Coordinate output precision = 32. Zoom measured in units of 2⁻³².');fig.subplots_adjust(left=.21,bottom=.27);rep=C['result']['parameter_output'];labels=['mean 1','mean 2','covariance 11','covariance 12','covariance 21','covariance 22'];centers=rep['mean']['center']+sum(rep['covariance']['center'],[]);radii=rep['mean']['radius']+sum(rep['covariance']['radius'],[]);true=CS[-1]['mean']+sum(CS[-1]['covariance'],[]);offsets=[f((Q(c)-Q(t))*(1<<32)) for c,t in zip(centers,true)];widths=[f(Q(r)*(1<<32)) for r in radii];ys=np.arange(6);ax.errorbar(offsets,ys,xerr=widths,fmt='o',color=BLUE,ecolor=TEAL,capsize=5,lw=2);ax.axvline(0,color=ORANGE,ls='--',label='Exact Joseph parameter');ax.set_yticks(ys,labels);ax.invert_yaxis();ax.set(xlabel='Reported center minus exact parameter, divided by 2⁻³²',xlim=(-11,11));ax.legend(fontsize=9,loc='upper right');fig.text(.5,.12,'Largest radius = 1/536870912, far below δ = 1/1000.',ha='center',size=11);save(fig,'13_output_intervals','Each horizontal interval is centered at the reported dyadic center, translated relative to the exact Joseph parameter and rescaled by 2³² for visibility. The dashed zero line is enclosed in all six intervals. These enclose the approximation parameters at B₆, not entrywise parameters of the exact posterior. The centers alone do not define another certified Gaussian.','Exact interval comparisons; graphical coordinates are numerical rescalings.',['coordinate.result.parameter_output','coordinate.states[-1]'])

