fig,(ax,)=make('Naive independent rounding breaks the cache','Scalar model P = 1, H = 1, R = 1. Precision p = 0.');off(ax)
box(ax,.03,.58,.25,.26,'Before update\nB = 0, G = 1');box(ax,.37,.58,.25,.26,'Ideal exact update\nB′ = 1/3, G′ = 1/3');box(ax,.71,.58,.25,.26,'Round both downward\nB̃ = 0, G̃ = 0',RED);arrow(ax,(.28,.71),(.37,.71));arrow(ax,(.62,.71),(.71,.71));box(ax,.13,.08,.3,.24,'Stored cache score\n2 G̃² = 0',TEAL);box(ax,.56,.08,.3,.24,'True residual score\n2 (1 − 2 B̃)² = 2',RED);arrow(ax,(.83,.58),(.71,.32),RED);arrow(ax,(.78,.58),(.28,.32));save(fig,'16_naive_rounded_cache','For the scalar model, τ=1/3 and the ideal first update has gain and residual both 1/3. Independently rounding both to zero fractional bits produces stored gain zero and stored residual zero. The cached score reports zero, although the true residual remains one and true score is two. The final independent verifier rejects this candidate for ε=1/10.','Checked scalar counterexample to center-only rounded-cache invariants.',['rounded_counterexample','Komorebi/CachedRoundingBoundary.lean'])

fig,axs=make('Arithmetic boundaries belong in the contract','Exact cached updates and rounded parameter centers carry different obligations.',2);ax=axs[0];off(ax);box(ax,.07,.64,.85,.22,'Gain and cache updates\nExact rational arithmetic',BLUE);box(ax,.07,.32,.85,.22,'Final verifier and output\nOutward dyadic center/radius graph',TEAL);ax.text(.5,.13,'Hardware floating point requires\na separate execution refinement.',ha='center',va='center',size=11,color=GRAY);ax=axs[1];off(ax);ax.text(.5,.85,'A covariance-center warning',ha='center',weight='bold',size=13);ax.text(.5,.56,'Exact PSD covariance\n[[1/4, 3/4], [3/4, 9/4]]\n\nDown-rounded centers at p = 1\n[[0, 1/2], [1/2, 2]]',ha='center',va='center',size=12);ax.text(.5,.15,'v = (−3, 1):  vᵀ C̃ v = −1',ha='center',color=RED,size=12);save(fig,'17_arithmetic_boundary','The released selective updates use exact rationals, while the final verifier and parameter output use outward-rounded dyadic balls. A separate illustration shows why covariance centers cannot automatically be treated as a covariance: a PSD rank-one covariance rounds downward to a matrix with quadratic witness −1. This counterexample concerns center-only interpretation, not failure of the enclosing interval arrays.','Exact arithmetic contract and independent covariance-center counterexample.',['covariance_center_counterexample','README.md'])

